from PIL import Image
import numpy as np
im=np.asarray(Image.open('radiograph.jpg').convert('L')).astype(np.float32)
H,W=im.shape
def score(x,y,r=22,R=48):
    yy,xx=np.mgrid[0:H,0:W]
    d2=(xx-x)**2+(yy-y)**2
    inner=d2<=r*r
    ring=(d2>=R*R)&(d2<=(R+18)**2)
    return im[ring].mean()-im[inner].mean()
